using AngularApi.Contracts.DTO; using FluentValidation;
namespace AngularApi.Validators { public class UpdatePatientReviewDTOValidator : AbstractValidator<UpdatePatientReviewDTO> { public UpdatePatientReviewDTOValidator(){ RuleFor(x=>x.DoctorId).NotEmpty(); RuleFor(x=>x.WaitTimeRating).InclusiveBetween(1,5).When(x=>x.WaitTimeRating.HasValue); RuleFor(x=>x.BedsideMannerRating).InclusiveBetween(1,5).When(x=>x.BedsideMannerRating.HasValue); RuleFor(x=>x.OverallRating).InclusiveBetween(1,5).When(x=>x.OverallRating.HasValue); RuleFor(x=>x.Review).MaximumLength(ValidationConstants.ReviewMaxLength).When(x=>x.Review!=null); } } }
